/**
 * Bakes Natural Earth's 110m land outline into a plain SVG path string.
 *
 * Run by hand (`node scripts/build-world-land.mjs`), not on every build: the
 * source data never changes, and the generated file is committed. world-atlas
 * and topojson-client stay devDependencies, so nothing is added to what
 * consumers install - AstrocartographyMap draws real coastlines with no
 * runtime dependency and no tile server.
 *
 * Coordinates are emitted in a fixed 360x180 space (x = longitude + 180,
 * y = 90 - latitude) so the component only has to scale them, keeping the
 * projection decision where the drawing happens rather than baking a pixel
 * size in here.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { feature } from "topojson-client";

const require = createRequire(import.meta.url);
const topology = JSON.parse(readFileSync(require.resolve("world-atlas/land-110m.json"), "utf8"));
const land = feature(topology, topology.objects.land);

/** ~11km at the equator - far finer than a world map a few hundred px wide. */
const round = (n) => Math.round(n * 10) / 10;

function ringToPath(ring) {
  let d = "";
  let prevX = null;
  let prevY = null;
  for (const [lon, lat] of ring) {
    const x = round(lon + 180);
    const y = round(90 - lat);
    // Natural Earth's outline has long runs of near-identical points at this
    // precision; dropping the repeats is most of the size saving.
    if (x === prevX && y === prevY) continue;
    d += d === "" ? `M${x} ${y}` : `L${x} ${y}`;
    prevX = x;
    prevY = y;
  }
  return d === "" ? "" : `${d}Z`;
}

const paths = [];
for (const f of land.features) {
  const geom = f.geometry;
  const polygons = geom.type === "Polygon" ? [geom.coordinates] : geom.coordinates;
  for (const polygon of polygons) {
    for (const ring of polygon) {
      const d = ringToPath(ring);
      if (d) paths.push(d);
    }
  }
}

const d = paths.join("");
const out = `// Generated by scripts/build-world-land.mjs - do not edit by hand.
// Natural Earth 110m land outline (public domain), via world-atlas.
// Coordinate space is 360 wide x 180 tall: x = longitude + 180, y = 90 - latitude.

export const WORLD_LAND_PATH =
  "${d}";
`;

writeFileSync(new URL("../src/components/western/worldLand.ts", import.meta.url), out);
console.log(`world land: ${paths.length} rings, ${(d.length / 1024).toFixed(1)} KB of path data`);
